	["On battery, macOS may slow the graphics down, so the results would be lower than when plugged in."] = "Na bateriji, macOS može usporiti grafiku, pa bi rezultati bili niži nego kad je priključen.",
	["On: each place below uses the settings you pick for it."] = "Uključeno: svako mesto ispod koristi podešavanja koja za njega izaberete.",
	["On: when your goal can't be reached any other way, the System Check lowers render scale below 85% (down to 50%), with every other setting at its lowest. The 3D world gets softer; text and the interface stay sharp. Run the check again after turning it on."] = "Uključeno: kada se vaš cilj ne može dostići drugačije, System Check snižava render scale ispod 85% (do 50%), sa svim ostalim podešavanjima na najnižem. 3D svet postaje mekši; tekst i interfejs ostaju oštri. Pokrenite proveru ponovo posle uključivanja.",
	["On: your goal becomes a minimum and nothing caps the frame rate, so your Mac runs as fast as it can. It works harder and gets warmer."] = "Uključeno: vaš cilj postaje minimum i ništa ne ograničava frame rate, pa vaš Mac radi najbrže što može. Više radi i greje se.",
	["Open Mac-ever"] = "Otvori Mac-ever",
	["Open world"] = "Otvoreni svet",
	["Opens Mac-ever without setting up. Set up any time with Change Setup on the System Check tab, or /macever setup."] = "Otvara Mac-ever bez podešavanja. Podesite bilo kada preko Promeni setup na System Check kartici, ili /macever setup.",
	["Opens the System Check with a %d fps goal. This preset is tailored from a measurement of your Mac, so it needs one first."] = "Otvara System Check sa ciljem od %d fps. Ovaj preset je prilagođen merenju vašeg Mac-a, pa prvo treba jedno.",
	["Other addons: "] = "Drugi addoni: ",
	["Out of reach here: Apply gives the fastest setup, about %.0f fps (%s)."] = "Van dometa ovde: Primeni daje najbrže podešavanje, oko %.0f fps (%s).",
	["Out of reach here: about %.0f fps, even at %d%% render scale (%s)."] = "Van dometa ovde: oko %.0f fps, čak i na %d%% render scale (%s).",
	["Outlines drawn around targets and objects you mouse over."] = "Obrisi crtani oko meta i objekata iznad kojih držite miš.",
	["Overall brightness."] = "Ukupna svetlina.",
	["Predicted from what each setting cost on your Mac: what everything at maximum would give you here. The check doesn't run everything at maximum just to measure it, so your Mac stays cooler."] = "Predviđeno iz cene svakog podešavanja na vašem Mac-u: šta bi vam ovde dalo sve na maksimumu. Provera ne pokreće sve na maksimumu samo da bi to izmerila, pa vaš Mac ostaje hladniji.",
	["Predicted: about %.0f fps (%s)."] = "Predviđeno: oko %.0f fps (%s).",
	["Predicted: about %.0f fps at %d%% render scale (%s)."] = "Predviđeno: oko %.0f fps na %d%% render scale (%s).",
	["Prepares shaders in the background instead of pausing the game to do it."] = "Priprema shadere u pozadini umesto da pauzira igru da to uradi.",
	["Press Cmd+C to copy the report below (it's already selected), then paste it in a comment on Mac-ever's CurseForge page:"] = "Pritisnite Cmd+C da kopirate izveštaj ispod (već je izabran), pa ga nalepite u komentar na CurseForge stranici Mac-ever-a:",
	["Raid & Battleground Settings is off, so the Base values apply everywhere."] = "Raid & Battleground Settings je isključeno, pa se Base vrednosti primenjuju svuda.",
	["Raids & battlegrounds"] = "Raidovi i battlegroundi",
	["Raids & battlegrounds: the copies the game uses there while its Raid & Battleground Settings are on."] = "Raidovi i battlegroundi: kopije koje igra tamo koristi dok su njena Raid & Battleground Settings uključena.",
	["Raids and battlegrounds only: "] = "Samo raidovi i battlegroundi: ",
	["Ray-traced shadows. Not supported on Macs."] = "Ray-traced senke. Nije podržano na Mac-ovima.",
	["Re-measuring at the lowest settings"] = "Ponovno merenje na najnižim podešavanjima",
	["Recommended settings"] = "Preporučena podešavanja",
	["Recommended: "] = "Preporučeno: ",
	["Reduces the delay between your input and what you see."] = "Smanjuje kašnjenje između vašeg unosa i onoga što vidite.",
	["Reload First"] = "Prvo reload",
	["Reloads the interface. Forever's frame rate on Macs can drop over a long session, so reloading first gives the cleanest measurement."] = "Ponovo učitava interfejs. Forever frame rate na Mac-ovima može pasti tokom duge sesije, pa reload prvo daje najčistije merenje.",
	["Render scale goes below 85% because you allowed lower resolution, so the 3D world looks softer."] = "Render scale ide ispod 85% jer ste dozvolili nižu rezoluciju, pa 3D svet izgleda mekše.",
	["Render scale goes below 85%: the 3D world looks softer, but text and the interface stay sharp."] = "Render scale ide ispod 85%: 3D svet izgleda mekše, ali tekst i interfejs ostaju oštri.",
	["Report a Problem"] = "Prijavi problem",
	["Resets the settings on the game's own Graphics menu to their defaults, like the menu's Defaults button. Hidden settings aren't touched."] = "Vraća podešavanja iz grafičkog menija igre na podrazumevana, kao dugme Defaults u meniju. Hidden Settings se ne diraju.",
	["Resolution the 3D world is drawn at. Tip: 99% with FidelityFX looks crisper than 100%, because sharpening only runs below 100%."] = "Rezolucija na kojoj se crta 3D svet. Savet: 99% sa FidelityFX izgleda oštrije od 100%, jer se oštrenje primenjuje samo ispod 100%.",
	["Restore Originals"] = "Vrati originale",
	["Results vary between Macs, places in the world and game updates. Some changes, especially from the System Check and Hidden Settings, can cause visual problems, stutter or crashes."] = "Rezultati variraju između Mac-ova, mesta u svetu i ažuriranja igre. Neke promene, naročito iz System Check-a i Hidden Settings, mogu izazvati vizuelne probleme, trzanje ili rušenja.",
	["Run System Check"] = "Pokreni System Check",
	["Run the check"] = "Pokreni proveru",
	["Run the check to see your result here. Nothing changes until you apply it."] = "Pokrenite proveru da ovde vidite rezultat. Ništa se ne menja dok ga ne primenite.",
	["Select All"] = "Izaberi sve",
	["Selects the whole report again, so Cmd+C copies all of it."] = "Ponovo bira ceo izveštaj, pa Cmd+C kopira sve.",
	["Sends work to the GPU from a separate thread."] = "Šalje posao GPU-u iz posebne niti.",
	["Set Up Mac-ever"] = "Podesi Mac-ever",
	["Sets %s for %s."] = "Postavlja %s za %s.",
	["Settings for"] = "Podešavanja za",
	["Settings switch quickly while it runs, so stutter and glitches are normal and, rarely, the game crashes. The frame-rate cap is off, so your Mac will get warm."] = "Podešavanja se brzo menjaju dok radi, pa su trzanje i greške normalni i, retko, igra se sruši. Ograničenje frame rate-a je isključeno, pa će se vaš Mac zagrejati.",
	["Settings that restart the screen or the game window are left as they are."] = "Podešavanja koja restartuju ekran ili prozor igre ostaju kakva jesu.",
	["Settings the game's own menu doesn't show, for fine-tuning beyond the presets. What works on one Mac may not on another."] = "Podešavanja koja meni igre ne prikazuje, za fino podešavanje preko preseta. Ono što radi na jednom Mac-u ne mora na drugom.",
	["Settings: "] = "Podešavanja: ",
	["Setup: not set up"] = "Setup: nije podešeno",
	["Shadow Detail"] = "Detalj senki",
	["Sharpening strength: 0 is the strongest, 2 the weakest. Stronger looks crisper; too strong looks gritty. 0.2 is the game's default."] = "Jačina oštrenja: 0 je najjače, 2 najslabije. Jače izgleda oštrije; previše jako izgleda zrnasto. 0.2 je podrazumevano u igri.",
	["Sharpness of surface textures. Mainly uses video memory, little frame rate."] = "Oštrina tekstura površina. Uglavnom koristi video memoriju, malo frame rate-a.",
	["Show minimap button"] = "Prikaži dugme na minimapi",
	["Show the warning when opening Mac-ever"] = "Prikaži upozorenje pri otvaranju Mac-ever-a",
	["Shows a report of your Mac, setup and settings to copy and post on Mac-ever's CurseForge page. You can also type /macever report."] = "Prikazuje izveštaj o vašem Mac-u, setup-u i podešavanjima koji možete da kopirate i objavite na CurseForge stranici Mac-ever-a. Možete i ukucati /macever report.",
	["Smooths jagged edges by sampling each pixel several times. Costly at Retina resolutions."] = "Zaglađuje nazubljene ivice uzorkovanjem svakog piksela više puta. Skupo na Retina rezolucijama.",
	["Smooths jagged edges. FXAA is cheap; CMAA 2 cost about 56 fps on an M1 Pro in testing."] = "Zaglađuje nazubljene ivice. FXAA je jeftin; CMAA 2 je koštao oko 56 fps na M1 Pro u testiranju.",
	["Soft contact shadows in corners and where objects meet the ground. Adds depth; costs GPU time."] = "Meke kontaktne senke u uglovima i gde se objekti sastaju sa tlom. Dodaje dubinu; košta GPU vreme.",
	["Some can cause visual problems, stutter or crashes. Change one at a time; Restore Originals undoes Mac-ever's changes."] = "Neka mogu izazvati vizuelne probleme, trzanje ili rušenja. Menjajte jedno po jedno; Vrati originale poništava promene Mac-ever-a.",
	["Spell Density and Projected Textures aren't part of the check: they cost frame rate in big fights."] = "Spell Density i Projected Textures nisu deo provere: koštaju frame rate u velikim borbama.",
	["Spell effects drawn onto the ground, such as area-of-effect markers. Turning off hides combat cues."] = "Efekti čarolija iscrtani na tlu, kao oznake područja dejstva. Isključivanje skriva signale u borbi.",
	["Spreads rendering work across several CPU cores."] = "Raspoređuje posao renderovanja na više CPU jezgara.",
	["Stand still somewhere busy, out of combat, with the game in front."] = "Stanite negde gde je gužva, van borbe, sa igrom u prvom planu.",
	["Stand still somewhere busy, out of combat."] = "Stanite negde gde je gužva, van borbe.",
	["Step 1 of 3: Your Mac"] = "Korak 1 od 3: Vaš Mac",
	["Step 2 of 3: Choose your frame rate"] = "Korak 2 od 3: Izaberite frame rate",
	["Step 3 of 3: Run the System Check"] = "Korak 3 od 3: Pokrenite System Check",
	["Stopped. Your settings have been put back."] = "Zaustavljeno. Vaša podešavanja su vraćena.",
	["Stopped: a loading screen. Your settings have been put back."] = "Zaustavljeno: ekran učitavanja. Vaša podešavanja su vraćena.",
	["Stopped: combat started. Your settings go back once combat ends."] = "Zaustavljeno: borba je počela. Vaša podešavanja se vraćaju kad borba prestane.",
	["Stopped: too few frames to measure here. Your settings have been put back."] = "Zaustavljeno: premalo frame-ova za merenje ovde. Vaša podešavanja su vraćena.",
	["Stopped: you moved. Settings put back; stand still and try again."] = "Zaustavljeno: pomerili ste se. Podešavanja vraćena; stanite mirno i pokušajte ponovo.",
	["Stops the check and puts your settings back."] = "Zaustavlja proveru i vraća vaša podešavanja.",
	["Strength of the glow around bright lights."] = "Jačina sjaja oko jakih svetala.",
	["Stronger contrast and richer mid-tones for a punchier picture."] = "Jači kontrast i bogatiji srednji tonovi za upečatljiviju sliku.",
	["Switch Back"] = "Vrati nazad",
	["Switch settings in instances"] = "Menjaj podešavanja u instancama",
	["Switched back to your previous settings."] = "Vraćeno na vaša prethodna podešavanja.",
	["Switching back in %d second%s."] = "Vraćanje za %d s%s.",
	["Syncs frames to your screen to stop tearing. Limits frame rate to the screen's refresh rate."] = "Sinhronizuje frame-ove sa vašim ekranom da spreči tearing. Ograničava frame rate na osvežavanje ekrana.",
	["System Check result"] = "Rezultat System Check-a",
	["System Check result: the last check's recommendation."] = "Rezultat System Check-a: preporuka poslednje provere.",
	["System Check stopped for combat. Your settings go back as soon as combat ends."] = "System Check je zaustavljen zbog borbe. Vaša podešavanja se vraćaju čim borba prestane.",
	["System Check: %s didn't go back to how %s before the check. Restore Originals, or the game's own menu, puts %s back."] = "System Check: %s se nije vratilo kako %s pre provere. Vrati originale, ili meni igre, vraća %s nazad.",
	["System Check: your settings are back as they were."] = "System Check: vaša podešavanja su vraćena kakva su bila.",
	["Takes effect after you restart the game."] = "Stupa na snagu posle ponovnog pokretanja igre.",
	["The System Check and goal presets set these back to the game's defaults, apart from Mac-ever's fixed values, unless Keep my Hidden Settings is on. Changing them can cost frame rate or picture quality."] = "System Check i goal preseti vraćaju ova na podrazumevana igre, osim fiksnih vrednosti Mac-ever-a, osim ako je Zadrži moja Hidden Settings uključeno. Njihova promena može koštati frame rate ili kvalitet slike.",
	["The System Check and its results leave your Hidden Settings as they are, and measure with them. Available after your first System Check."] = "System Check i njegovi rezultati ostavljaju vaša Hidden Settings kakva jesu i mere sa njima. Dostupno posle vašeg prvog System Check-a.",
	["The System Check sets Hidden Settings back to the game's defaults and tunes only Standard Settings, unless Keep my Hidden Settings is on."] = "System Check vraća Hidden Settings na podrazumevana igre i podešava samo Standard Settings, osim ako je Zadrži moja Hidden Settings uključeno.",
	["The \"Before you start\" message: what Mac-ever does, that results vary, and how to undo everything."] = "Poruka 'Pre nego što počnete': šta Mac-ever radi, da rezultati variraju i kako sve da poništite.",
	["The check couldn't start."] = "Provera nije mogla da počne.",
	["The fastest setup within your rules: render scale stays at 85% or above unless you allow lower resolution."] = "Najbrže podešavanje u okviru vaših pravila: render scale ostaje na 85% ili više osim ako dozvolite nižu rezoluciju.",
	["The frame rate stays capped at your goal, but graphics are only raised until the Mac could still reach goal x headroom without the cap (60 fps x 1.6 = about 96). The GPU then has spare time every frame, so it runs cooler and the fans stay quiet. Run the System Check again after changing it."] = "Frame rate ostaje ograničen na vaš cilj, ali se grafika podiže samo dok bi Mac i dalje mogao da dostigne cilj x headroom bez ograničenja (60 fps x 1.6 = oko 96). GPU tada ima slobodnog vremena u svakom frame-u, pa radi hladnije i ventilatori ostaju tihi. Pokrenite System Check ponovo posle promene.",
	["The frame rate the System Check tunes for. Graphics stay as high as that frame rate allows."] = "Frame rate za koji System Check podešava. Grafika ostaje onoliko visoka koliko taj frame rate dozvoljava.",
	["The game reports the graphics chip, but not which Mac it's in. A MacBook Air has no fan, so it slows down as it warms up."] = "Igra prijavljuje grafički čip, ali ne i koji je to Mac. MacBook Air nema ventilator, pa usporava kako se zagreva.",
	["The game wouldn't accept %s, so those levels were left out."] = "Igra nije prihvatila %s, pa su ti nivoi izostavljeni.",
	["The graphics share your Mac's memory, so 8 GB leaves the game less room. With 16 GB or more, memory isn't the limit."] = "Grafika deli memoriju vašeg Mac-a, pa 8 GB ostavlja igri manje prostora. Sa 16 GB ili više, memorija nije ograničenje.",
	["The last System Check didn't finish, so your settings have been put back as they were."] = "Poslednji System Check se nije završio, pa su vaša podešavanja vraćena kakva su bila.",
	["The minimap button's libraries are missing. Type /macever to open Mac-ever."] = "Biblioteke dugmeta na minimapi nedostaju. Ukucajte /macever da otvorite Mac-ever.",
	["These pages give you direct control over the game's graphics settings, including ones that can make the game unstable."] = "Ove stranice daju direktnu kontrolu nad grafičkim podešavanjima igre, uključujući ona koja mogu učiniti igru nestabilnom.",
	["This computer's graphics chip (%s) isn't Apple Silicon. %s\n\n%s"] = "Grafički čip ovog računara (%s) nije Apple Silicon. %s\n\n%s",
	["Trying %d%% render scale"] = "Isprobavanje %d%% render scale",
	["Tunes %d settings and takes %s."] = "Podešava %d podešavanja i traje %s.",
	["Turns the background frame-rate cap on or off."] = "Uključuje ili isključuje ograničenje frame rate-a u pozadini.",
	["Turns the foreground frame-rate cap on or off."] = "Uključuje ili isključuje ograničenje frame rate-a u prvom planu.",
	["Undoes Mac-ever's changes: every setting Mac-ever has changed goes back to how it was before."] = "Poništava promene Mac-ever-a: svako podešavanje koje je Mac-ever promenio vraća se kako je bilo pre.",
	["Use a separate, usually lower, set of quality settings in raids and battlegrounds."] = "Koristi poseban, obično niži skup podešavanja kvaliteta u raidovima i battlegroundima.",
	["Used in raids and battlegrounds only."] = "Koristi se samo u raidovima i battlegroundima.",
	["Uses extra GPU features when available. Off makes the game act as if the GPU had only the basics."] = "Koristi dodatne GPU funkcije kada su dostupne. Isključeno čini da se igra ponaša kao da GPU ima samo osnovno.",
	["Volumetric fog and other compute-shader effects. A large GPU cost."] = "Volumetrijska magla i drugi compute-shader efekti. Veliki trošak GPU-a.",
	["Whether grass, cloth and objects react to you and to creatures."] = "Da li trava, tkanina i objekti reaguju na vas i na stvorenja.",
	["Which Mac you have and the frame rate you want. You can also type /macever setup."] = "Koji Mac imate i koji frame rate želite. Možete i ukucati /macever setup.",
	["Working out the best settings"] = "Određivanje najboljih podešavanja",
	["You can also type /macever in chat."] = "Možete i ukucati /macever u čet.",
	["You get %d seconds to keep or switch back, and Restore Originals undoes it later."] = "Imate %d sekundi da zadržite ili vratite, a Vrati originale to kasnije poništava.",
	["You get %d seconds to keep the settings or switch back."] = "Imate %d sekundi da zadržite podešavanja ili ih vratite.",
	["You get %d seconds to keep them or switch back."] = "Imate %d sekundi da ih zadržite ili vratite.",
	["You're in combat, so the previous settings come back as soon as combat ends."] = "U borbi ste, pa se prethodna podešavanja vraćaju čim borba prestane.",
	["Your Mac managed %.0f fps at best, with every setting at the lowest that keeps the picture sharp (render scale 85%%). Apply Recommended to get that, or pick a lower goal.%s"] = "Vaš Mac je postigao %.0f fps u najboljem slučaju, sa svim podešavanjima na najnižem koje drži sliku oštrom (render scale 85%%). Primenite preporučeno da to dobijete, ili izaberite niži cilj.%s",
	["Your Mac managed %.0f fps at best. Lowering resolution wouldn't help: something else limits the frame rate here, most often the CPU. Apply Recommended to get that, or pick a lower goal."] = "Vaš Mac je postigao %.0f fps u najboljem slučaju. Snižavanje rezolucije ne bi pomoglo: nešto drugo ograničava frame rate ovde, najčešće CPU. Primenite preporučeno da to dobijete, ili izaberite niži cilj.",
	["Your Mac managed %.0f fps with render scale down to %d%% and every other setting at its lowest. Apply Recommended to get that, or pick a lower goal."] = "Vaš Mac je postigao %.0f fps sa render scale spuštenim na %d%% i svim ostalim podešavanjima na najnižem. Primenite preporučeno da to dobijete, ili izaberite niži cilj.",
	["Your frame rate drifted %+.0f%% during the check, so the numbers are less reliable. Try Reload First and run it again."] = "Vaš frame rate je odlutao %+.0f%% tokom provere, pa su brojevi manje pouzdani. Probajte Prvo reload i pokrenite ponovo.",
	["Your graphics chip: %s. The game can't tell which kind of Mac it's in or how much memory it has, so Mac-ever asks."] = "Vaš grafički čip: %s. Igra ne zna koja vrsta Mac-a je u pitanju ni koliko ima memorije, pa Mac-ever pita.",
	["Your own settings"] = "Vaša sopstvena podešavanja",
	["Your own settings: what you had before arriving, unchanged."] = "Vaša sopstvena podešavanja: ono što ste imali pre dolaska, nepromenjeno.",
	["Your picture already matches %s."] = "Vaša slika već odgovara %s.",
	["Your picture settings were changed to Mac-ever's Standard picture. Use the sliders to discover your preference, or pick a picture look."] = "Vaša podešavanja slike promenjena su na Standardnu sliku Mac-ever-a. Koristite klizače da otkrijete šta vam odgovara, ili izaberite izgled slike.",
	["Your settings already match %s."] = "Vaša podešavanja već odgovaraju %s.",
	["Your settings now"] = "Vaša podešavanja sada",
	["Your setup:"] = "Vaš setup:",
	["|cff40ff40Raise to "] = "|cff40ff40Povećaj na ",
	["|cffccccccNo change|r"] = "|cffccccccBez promene|r",
	["|cffccccccalmost nothing|r"] = "|cffccccccgotovo ništa|r",
	["|cffccccccnot measured|r"] = "|cffccccccnije izmereno|r",
	["|cffff8c8cSomething went wrong:|r "] = "|cffff8c8cNešto je pošlo naopako:|r ",
	["|cffff9933Caution|r settings can cause visual problems or refresh the game window. |cffff8c8cAdvanced|r settings can crash the game."] = "|cffff9933Oprez|r podešavanja mogu izazvati vizuelne probleme ili osvežiti prozor igre. |cffff8c8cNapredna|r podešavanja mogu srušiti igru.",
	["|cffff9933Lower to "] = "|cffff9933Smanji na ",
	["|cffffd100+|r  Show %d setting%s"] = "|cffffd100+|r  Prikaži podešavanja (%d)%s",
	["|cffffd100-|r  Hide"] = "|cffffd100-|r  Sakrij",
	["|cffffd100MacBook Air:|r We recommend running System Check when your Mac has warmed up, as it gives a more accurate testing scenario for Mac-ever"] = "|cffffd100MacBook Air:|r Preporučujemo pokretanje System Check-a kada se vaš Mac zagreje, jer daje precizniji scenario testiranja za Mac-ever",
	["s"] = "",
	["it was"] = "je bilo",
	["they were"] = "su bila",
	["it"] = "ga",
	["them"] = "ih",
	["Keep"] = "Zadrži",
	["Keep this setting as it is: the System Check's result and the presets never change it, and the rest is worked out around it. Change it yourself under Standard Settings."] = "Zadržite ovo podešavanje kakvo jeste: rezultat System Check-a i preseti ga nikad ne menjaju, a ostalo se računa oko njega. Menjajte ga sami pod Standard Settings.",
	["How much frame rate each setting takes at its highest level, measured on your Mac. Tick Keep to leave a setting as it is."] = "Koliko frame rate-a svako podešavanje uzima na najvišem nivou, izmereno na vašem Mac-u. Štiklirajte Zadrži da podešavanje ostane kakvo jeste.",
	["Starting point for your Mac, not measured yet. Run a System Check to fine-tune it."] = "Početna tačka za vaš Mac, još nije izmereno. Pokrenite System Check da je fino podesite.",
	["Turn on 'Let Mac-ever lower resolution to reach your goal' to use a lower render scale: it saves the most heat."] = "Uključite 'Dozvoli Mac-ever-u da snizi rezoluciju da bi dostigao cilj' da koristite niži render scale: on najviše štedi toplotu.",
})
